// Complete, fictional local preview. No requests, real accounts, or real credentials.
let growthTab='overview',handbookKind='all',handbookQuery='',handbookScope='all',handbookPage=0,detailId=null,authTab='login',pendingModal=null;
let adminAccountOrigin=null;
function setPage(page){
  if(page==='admin-account'&&currentPage!==page){
    adminAccountOrigin=state.preview.role==='admin'&&(adminRoutes.some(route=>route[0]===currentPage)||currentPage==='preview')?currentPage:null;
  }
  routineSetPage(page);
}
const dimensions=['体能','智力','情商','创造力','规划力','健康','幸福感','感恩','意义感','心理韧性','开放性','审美','诚信'];
const decisionItems=[
  ['layout','页面组织','今天、手账、计划、成长、我的；手机单列与底部导航。','已讨论'],
  ['records','日记与回顾','同一入口分区保存原文、AI 问题、我的回答、AI 分析。','已确认'],
  ['plans','计划结果','完成／部分完成先建议再入账；未完成在卡片内确认锁定。','已确认'],
  ['account','注册与找回','预览采用用户名＋邮箱、邮件找回及主动改密；无需邀请码。','候选'],
  ['admin','管理后台','独立管理导航；用户人数/列表、公告、站点设置及操作记录。','候选'],
  ['ai','默认 AI','站点默认、自配或关闭；默认服务的额度和运营预算尚未确定。','候选'],
  ['economy','主线金币','按有效投入／成果分档；展示金额和上限均为示例。','方向已确认'],
  ['export','本地保存','预览 Markdown、HTML、JSON、CSV；默认格式和范围待选。','候选'],
  ['dates','补记统计','日常默认当天，可补选日期；补记对连续天数的口径待选。','候选'],
  ['achievements','动态成就','AI 提供证据与候选，经核实后领取；金额和叠加待选。','候选']
];
function initializePreview(reset=false){
  if(reset)adminAccountOrigin=null;
  if(state.preview&&!reset)return;
  growthTab='overview';handbookKind='all';handbookQuery='';handbookScope='all';handbookPage=0;detailId=null;authTab='login';
  state.date='2026-10-16';state.records.forEach(record=>record.date=state.date);
  state.plans.find(plan=>plan.id==='strength').schedule.anchor='2026-10-16';
  state.records.push({id:'project',kind:'event',date:state.date,time:'16:10',title:'第一次把练习项目部署到云端',content:'跟着教程完成了一个小项目的云端部署。遇到报错后查了一遍配置，也向朋友请教了。虽然还不熟悉，但终于跑通了整个过程。'});
  for(const day of ['2026-10-10','2026-10-11','2026-10-12','2026-10-13','2026-10-14','2026-10-15'])state.records.push({id:'history-diary-'+day,kind:'diary',date:day,time:'21:30',title:'把今天的一点收获留下来',content:'今天完成了一点复习，也给自己留了休息的时间。慢慢来，明天继续。'});
  state.records.push({id:'diary@2026-10-16',kind:'diary',date:state.date,time:'21:10',title:'有收获，也有一点着急的一天',content:'今天整理了高数错题，又完成了一次项目部署。卡住的时候有一点着急，不过最后还是往前走了一步。明天想把今天碰到的问题整理成自己的笔记。'});
  state.careDays={'2026-10-16':state.care};state.reviewDays={};state.review=freshReview();state.reviewDays[state.date]=state.review;
  state.review.note=state.records.find(record=>record.id==='diary@2026-10-16').content;state.review.diaryId='diary@2026-10-16';state.review.complete=true;
  const question='遇到配置问题时，有没有什么帮助你继续推进的瞬间？',answer='朋友提醒我先看报错的第一行，一下子找到了检查的方向。';
  state.review.answers=[{sessionId:'seed-review',questionId:'seed-question',question,answer,skipped:false}];
  state.review.sessions=[{id:'seed-review',state:'finished',startedAt:'2026-10-16T21:15:00+08:00',endedAt:'2026-10-16T21:17:00+08:00',model:'本机脚本示例',snapshot:{diary:state.review.note,saved:true},turns:[{id:'seed-question',index:0,question,answer,state:'answered',askedAt:'2026-10-16T21:15:00+08:00',answeredAt:'2026-10-16T21:16:00+08:00'}],analysis:{source:'demo',text:'分析示例：你在卡住的时候寻求了帮助，并找到了下一步。这个片段可以与今天的原文一起回看，不需要改写你的日记。'}}];
  state.preview={role:'user',profile:{username:'xiaolin',name:'小林',email:'friend@example.com'},neutral:false,ai:{source:'site',provider:'siliconflow',model:'XingChenAGI/Xing4.0-29B',status:'ready',version:1},goals:[{id:'exam',name:'考研复习',main:true,note:'把基础打牢，每周复盘一次。'},{id:'fitness',name:'恢复规律运动',main:false,note:'按适合自己的节奏，慢慢找回习惯。'}],coinLedger:[{id:'start',amount:80,title:'未评估基线启动资金',source:'示例起点'}],products:[{id:'tea',name:'一杯喜欢的饮品',yuan:15,coins:30},{id:'movie',name:'看一部想看的电影',yuan:45,coins:90},{id:'rest',name:'留给自己的半小时',yuan:0,coins:12}],vouchers:[],claimed:[],challenge:null,notice:{title:'欢迎来这里留一页',body:'先记录，再慢慢找到适合自己的节奏。',published:true,version:1},noticeDismissed:0,registrationOpen:true,accountPaused:false,decisions:{},feedback:''};
  for(const record of state.records.filter(record=>record.kind!=='diary')){record.version=1;record.analysisIntent='later';record.analysisStatus='idle';}
  sessionDraft='';persist();
}
function heading(title,subtitle,eyebrow='LifeXP · 一页一日'){return `<header class="masthead"><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></header>`;}
function candidateNote(text){return `<div class="proposal-note"><span class="candidate">候选体验</span> ${text}</div>`;}
function balance(){return state.preview.coinLedger.reduce((sum,row)=>sum+row.amount,0)+state.ledger.reduce((sum,row)=>sum+row.suggestion.coins,0);}
function walletRows(){return [...state.preview.coinLedger,...state.ledger.map(row=>({id:row.key,amount:row.suggestion.coins,title:row.title,source:row.goal||'计划入账'}))];}
function currentGoal(){return state.preview.goals.find(goal=>goal.main);}
function learningProgress(){
  const ids=new Set(state.ledger.filter(row=>row.goal==='考研复习').map(row=>row.recordId));
  const goal=state.preview.goals.find(goal=>goal.name==='考研复习');
  for(const record of state.records)if(record.confirmed&&record.goalId===goal?.id)ids.add(record.sameFactAs||record.id);
  for(const item of Object.values(state.occurrences))if(item.settled&&state.plans.find(plan=>plan.id===item.planId)?.goal==='考研复习')ids.add(item.recordId);
  return ids.size;
}
function modelCaption(){const model=state.preview.ai;return model.source==='off'?'AI 已关闭':model.source==='site'?'站点默认 · 示例模型':`${providers[model.provider].name} · ${model.model}`;}
function nav(){
  const admin=state.preview.role==='admin';
  const parent=admin?(currentPage==='admin-account'?'admin':currentPage):({review:'handbook',detail:'handbook',goals:'plans',settings:'my',security:'my',export:'my',admin:'my',guide:'my',auth:'my',preview:'my'}[currentPage]||currentPage);
  const items=admin?adminRoutes:[['today','今天','today'],['handbook','手账','review'],['plans','计划','move'],['growth','成长','move'],['my','我的','guide']];
  for(const id of ['desktop-nav','mobile-nav'])document.getElementById(id).innerHTML=items.map(([key,label,icon])=>`<button data-nav="${key}" ${parent===key?'aria-current="page"':''}>${svg(icon)}<span>${label}</span></button>`).join('');
  document.querySelector('.side-foot').innerHTML=admin?'lifexp_admin<span>独立管理工作区</span><button class="link-btn" data-nav="admin-account">账号安全</button>':`${esc(state.preview.profile.name)}<span>Asia/Shanghai · 日常账号</span>`;
}
function today(){
  const notice=state.preview.notice,announcement=notice.published&&state.preview.noticeDismissed!==notice.version?`<div class="announcement"><div><strong>${esc(notice.title)}</strong><p>${esc(notice.body)}</p></div><button class="link-btn" data-suite="dismiss-notice" aria-label="收起公告">×</button></div>`:'';
  return announcement+routineToday()+`<section class="card today-recent"><div class="section-head"><h2>今天已经留下的 <span class="count">${dayFacts().length} 条</span></h2><button class="link-btn" data-nav="handbook">去手账查看 →</button></div>${dayFacts().slice(0,2).map(recordListItem).join('')}</section>`;
}
function recordListItem(record){const diary=record.kind==='diary';return `<article class="record"><div class="record-header"><p class="meta">${esc(record.date)} · ${esc(record.time)}</p><span class="badge ${diary?'green':'gray'}">${diary?'日记':'事件'}</span></div><button class="record-link" data-open-record="${esc(record.id)}"><h3>${esc(record.title)}</h3><p class="record-preview">${esc(record.content)}</p></button></article>`;}
function handbook(){
  const records=state.records.filter(record=>(handbookScope!=='today'||record.date===state.date)&&(handbookKind==='all'||(handbookKind==='diary'?record.kind==='diary':record.kind!=='diary'))&&(!handbookQuery||(record.title+' '+record.content).toLowerCase().includes(handbookQuery.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));
  const pages=Math.max(1,Math.ceil(records.length/5));handbookPage=Math.min(handbookPage,pages-1);
  return heading('手账','事件与日记分别保留，随时回来看。')+`<div class="subnav"><button data-handbook="all" aria-pressed="${handbookKind==='all'}">全部</button><button data-handbook="event" aria-pressed="${handbookKind==='event'}">事件</button><button data-handbook="diary" aria-pressed="${handbookKind==='diary'}">日记</button><button data-nav="review">写今天的日记</button></div><section class="card"><div class="filter-row"><label>搜索原文<input id="handbook-search" value="${esc(handbookQuery)}" placeholder="一句话、一件事…"></label><label>范围<select id="handbook-scope"><option value="all">所有日期</option><option value="today">预览当天</option></select></label><button class="btn" data-suite="search">搜索</button></div><p class="small muted" style="margin-bottom:17px">只搜你写下的原文，AI 问答与分析单独保留。</p><div id="handbook-results">${records.slice(handbookPage*5,handbookPage*5+5).map(recordListItem).join('')||'<p class="suite-empty">没有找到这段原文，换个词试试。</p>'}</div><div class="pagination"><button class="btn small-btn" data-page-step="-1" ${handbookPage===0?'disabled':''}>上一页</button><span>${records.length} 条 · ${handbookPage+1} / ${pages}</span><button class="btn small-btn" data-page-step="1" ${handbookPage+1>=pages?'disabled':''}>下一页</button></div></section>`;
}
function eventDetail(){
  const record=state.records.find(record=>record.id===detailId);if(!record)return heading('记录暂不可见','可以回到手账查找。');
  const fromPlan=state.ledger.some(row=>row.recordId===record.id),status=fromPlan?'confirmed':record.analysisStatus||'idle',suggestion=record.suggestion,locked=record.confirmed||fromPlan;
  const goal=state.preview.goals.find(goal=>goal.id===record.goalId);
  const statusHTML={idle:record.analysisIntent==='never'?'只记录 · 不分析':'还没有发起分析',queued:'分析中，原文已保存',failed:'本次分析失败，原文保留。可以重试。',needsInput:'需要补充与这件事相关的信息',ready:'建议已生成，尚未入账',confirmed:'已确认入账'}[status];
  return `<button class="link-btn" data-nav="handbook">← 返回手账</button>`+heading(record.title,'原文与分析分开保存。','事件详情')+`<section class="card"><div class="record-header"><span class="badge green">原文已保存</span><span class="small muted">${esc(record.date)} · ${esc(record.time)}</span></div><p class="detail-original">${esc(record.content)}</p><div class="record-actions"><button class="btn small-btn" data-suite="edit-event">编辑原文</button><button class="btn quiet small-btn" data-suite="related">查看疑似关联示例</button></div>${record.sameFactAs?'<p class="small muted" style="margin-top:12px">已由你确认关联，同一实际行动只计奖一次；两份原文都保留。</p>':''}</section><section class="card detail-block"><div class="section-head"><h2>分析与建议</h2><span class="badge ${status==='confirmed'?'green':status==='failed'?'amber':'gray'}">${esc(statusHTML)}</span></div>${status==='needsInput'?'<p class="dashboard-quote">这次行动实际做了多少、完成了哪一步？可以补充与这件事相关的内容。</p><textarea id="event-supplement" placeholder="例如：整理了三道错题，并独立做对了一道同类题。"></textarea>':''}${suggestion?`<p class="dashboard-quote">${esc(suggestion.reason)}</p><div class="info-line"><span>${esc(suggestion.attribute)}建议</span><strong>+${suggestion.delta} <span class="scope-tag">示例</span></strong></div><div class="info-line"><span>有效投入／成果档位</span><strong>${esc(suggestion.grade)}</strong></div><div class="info-line"><span>金币建议</span><strong class="money">基础 +2 ${suggestion.bonus?`＋主线 +${suggestion.bonus}`:''} 币 <span class="scope-tag">示例</span></strong></div><details style="margin-top:16px"><summary class="small muted">查看完整依据</summary><p class="dashboard-quote">依据这条记录的实际行动提出建议，不从一次表现推断永久能力。主线为${esc(goal?.name||'未关联')}；展示数值不是已批准规则。</p></details>`:''}${!locked?`<div class="form-grid"><label>关联目标（选填）<select id="event-goal"><option value="">独立事件</option>${state.preview.goals.map(goal=>`<option value="${goal.id}" ${record.goalId===goal.id?'selected':''}>${esc(goal.name)}${goal.main?' · 当前主线':''}</option>`).join('')}</select></label><label>投入／成果演示档位<select id="event-grade"><option value="light">有一点实际行动</option><option value="steady" selected>有明确投入或进展</option><option value="deep">有持续投入或具体成果</option></select></label><details><summary class="small muted">切换分析演示结果</summary><select id="analysis-outcome"><option value="ready">生成建议</option><option value="needsInput">待补充</option><option value="failed">调用失败</option></select></details></div><div class="record-actions">${status==='queued'?'<button class="btn" data-suite="cancel-event">取消分析</button>':`<button class="btn ${suggestion?'':'primary'}" data-suite="analyze-event">${status==='failed'?'重试分析':status==='needsInput'?'保存补充并分析':suggestion?'重新生成示例':'现在分析'}</button>`}${suggestion?'<button class="btn primary" data-suite="confirm-event">确认入账</button>':''}</div>`:'<p class="success-box">本次实际流水已记录，再次查看不会重复入账。</p>'}<p class="subtle-note">${esc(modelCaption())} · 分析为本机脚本演示</p></section>`;
}
function planOverview(){const goal=currentGoal();return `<section class="card goal-hero"><div class="section-head"><h2>当前主线 · ${esc(goal?.name||'尚未选择')}</h2><span class="badge">目标与计划</span></div><p>按有效投入与成果体现侧重点。具体金币档位仍待确认。</p><button class="btn small-btn" data-nav="goals">管理目标与主线</button></section>`+planningPage();}
function goalsPage(){return heading('目标与主线','先选想走的方向，再安排具体行动。')+candidateNote('一次一个当前主线及切换方式为预览建议；已入账历史不重算。')+`<div class="suite-grid"><section class="card"><h2 style="margin-bottom:18px">我的目标</h2>${state.preview.goals.map(goal=>`<article class="goal-tile"><div class="row between"><h3>${esc(goal.name)}</h3>${goal.main?'<span class="badge">当前主线</span>':''}</div><p>${esc(goal.note||'从一个小行动开始。')}</p><p>已关联 ${state.plans.filter(plan=>plan.goal===goal.name).length} 项计划</p><div class="row wrap">${!goal.main?`<button class="btn small-btn" data-main-goal="${goal.id}">设为当前主线</button>`:''}<button class="link-btn" data-nav="plans">安排具体行动 →</button></div></article>`).join('')}</section><section class="card"><h2>写下一个目标</h2><div class="form-grid"><label>目标名称<input id="goal-name" maxlength="100" placeholder="例如：完成数学基础复习"></label><label>为什么想做这件事（选填）<textarea id="goal-note" maxlength="1000" placeholder="用自己的话说就好。"></textarea></label><button class="btn primary" data-suite="add-goal">保存目标</button></div><p class="subtle-note">新建目标不会自动发奖，也不会把随口想法变成每日任务。</p></section></div>`;}
function totalDayStats(){return `<div class="suite-grid">${[['event','事件记录'],['diary','日记']].map(([kind,label])=>{const counts=recordDays(kind);return `<section class="card"><h2>${label}</h2><div class="stat-mini"><div><strong>${counts.total}</strong><span>累计天数</span></div><div><strong>${counts.current}</strong><span>当前连续</span></div><div><strong>${counts.longest}</strong><span>最长连续</span></div></div><p class="subtle-note">一天多条只计一天。</p></section>`}).join('')}</div>`;}
function attributeValue(name){return Math.round((50+state.ledger.filter(row=>row.suggestion.attribute===name).reduce((sum,row)=>sum+row.suggestion.delta,0)+state.records.filter(record=>record.confirmed&&!record.reusedSettlement&&record.suggestion?.attribute===name).reduce((sum,record)=>sum+record.suggestion.delta,0))*10)/10;}
function radarHTML(){const points=dimensions.map((name,i)=>{const angle=2*Math.PI*i/dimensions.length-Math.PI/2,r=attributeValue(name)*1.35;return `${220+Math.cos(angle)*r},${180+Math.sin(angle)*r}`;}).join(' ');return `<svg class="radar" viewBox="0 0 440 360" role="img" aria-label="13 项游戏属性雷达图">${[45,90,135].map(radius=>`<circle cx="220" cy="180" r="${radius}" stroke="#e0e5f4" fill="none"/>`).join('')}${dimensions.map((name,i)=>{const a=2*Math.PI*i/dimensions.length-Math.PI/2;return `<line x1="220" y1="180" x2="${220+Math.cos(a)*135}" y2="${180+Math.sin(a)*135}" stroke="#e0e5f4"/><text x="${220+Math.cos(a)*166}" y="${185+Math.sin(a)*156}" text-anchor="middle">${name}</text>`}).join('')}<polygon points="${points}" fill="#4058d630" stroke="#4058d6" stroke-width="2"/></svg>`;}
function growth(){
  const tabs=[['overview','概览'],['stats','记录与属性'],['achievements','成就'],['shop','奖励商店'],['challenge','挑战']];
  let body='';
  if(growthTab==='overview')body=`<section class="card goal-hero"><h2>${state.preview.neutral?'从未评估基线开始积累':'先选择游戏起点'}</h2><p>50 是中性游戏起点，不代表能力已经熟练。之后迁入旧评估数据另行办理。</p>${state.preview.neutral?'<span class="badge green">未评估基线 · 已选择</span>':'<button class="btn primary" data-suite="neutral">用未评估基线开始</button>'}</section>${totalDayStats()}<div class="suite-grid" style="margin-top:20px"><section class="card"><p class="preview-title">我的金币</p><strong class="coin-number">${balance()} <small style="font-size:14px;font-weight:400">币</small></strong><p class="subtle-note">这里的金额、奖励均为虚构示例。</p><button class="link-btn" data-growth="shop">去挑一个小奖励 →</button></section><section class="card"><h2>今天的一点进展</h2><p class="dashboard-quote">原文记录 ${dayFacts().length} 条。完成记录会留下来，选择分析后再决定是否入账。</p><button class="link-btn" data-nav="handbook">回看今天 →</button></section></div>`;
  if(growthTab==='stats')body=totalDayStats()+`<div class="suite-grid" style="margin-top:20px"><section class="card"><div class="section-head"><h2>能力数值</h2><span class="badge gray">${state.preview.neutral?'未评估基线':'游戏起点预览'}</span></div>${dimensions.map(name=>`<details class="attribute-row"><summary><strong>${name}</strong><span>${attributeValue(name)} / 100</span></summary><div class="progress"><span style="width:${Math.min(100,attributeValue(name))}%"></span></div><p>用于观察游戏中的积累，不是精确能力测量。这里不会把未评估的 50 标成“熟练”。</p></details>`).join('')}</section><section class="card"><h2>能力雷达图</h2>${radarHTML()}<p class="subtle-note">固定 0～100 轴；完整数值见能力列表。</p></section></div>`;
  if(growthTab==='achievements')body=achievementPage();
  if(growthTab==='shop')body=shopPage();
  if(growthTab==='challenge')body=challengePage();
  return heading('成长','回看已经留下的，也为下一步留一点期待。')+`<div class="subnav">${tabs.map(([id,label])=>`<button data-growth="${id}" aria-pressed="${growthTab===id}">${label}</button>`).join('')}</div>`+body;
}
function achievementPage(){const days=recordDays('diary'),claimed=state.preview.claimed.includes('first-project');return `<div class="suite-grid"><section class="card achievement-card"><div class="achievement-icon">✦</div><h2>连续留下一页 · 7 天</h2><p class="dashboard-quote">已经连续记录 ${days.current} 天日记。</p><span class="badge ${days.longest>=7?'green':'gray'}">${days.longest>=7?'里程碑已达成':'继续积累中'}</span></section><section class="card achievement-card"><div class="achievement-icon">✧</div><h2>连续写日记 30 天</h2><div class="progress"><span style="width:${Math.min(100,days.current/30*100)}%"></span></div><p class="small muted">${days.current} / 30 天 · 已有固定成就</p></section></div><section class="card" style="margin-top:20px"><div class="section-head"><h2>AI 发现的里程碑</h2><span class="candidate">领取与额度候选</span></div><h3>第一次完成云端部署</h3><p class="dashboard-quote">依据：今天的项目记录。第一次把练习项目从本机带到云端，值得纪念。</p><p class="small muted">系统先核实原文和已有成就；不会把同一个里程碑换个名字重复发奖。</p><div class="record-actions">${claimed?'<span class="badge green">已加入成就墙 · 示例奖励 +10 币</span>':'<button class="btn primary" data-suite="claim-achievement">确认领取 · 示例 +10 币</button><button class="btn quiet" data-suite="ignore-achievement">暂时忽略</button>'}<button class="link-btn" data-open-record="project">查看依据 →</button></div></section>`;}
function shopPage(){return `<section class="card"><div class="ledger-summary"><div><p class="small muted">我的金币</p><strong class="coin-number">${balance()} <small style="font-size:14px">币</small></strong></div><span class="scope-tag">全部金额仅用于预览</span></div><details><summary class="small muted">查看金币流水</summary>${walletRows().map(row=>`<div class="wallet-row ${row.amount<0?'negative':''}"><div>${esc(row.title)}<small>${esc(row.source)}</small></div><strong>${row.amount>0?'+':''}${row.amount} 币</strong></div>`).join('')}</details></section><section class="card" style="margin-top:20px"><div class="section-head"><h2>奖励商店</h2><button class="link-btn" data-suite="add-product">＋ 添加想要的东西</button></div><div class="suite-grid">${state.preview.products.map(product=>`<article class="reward-card"><h3>${esc(product.name)}</h3><div class="reward-price"><span class="badge gray">${product.yuan?product.yuan+' 元':'时间奖励'}</span><strong class="money">${product.coins} 币</strong></div><p>初始定价仅为示例，可按自己的情况调整。</p><div class="record-actions"><button class="btn primary small-btn" data-redeem="${product.id}" ${balance()<product.coins?'disabled':''}>兑换</button><button class="btn small-btn" data-price="${product.id}">调整价格</button></div></article>`).join('')}</div></section><section class="card" style="margin-top:20px"><h2>我的奖励券</h2>${state.preview.vouchers.length?state.preview.vouchers.map(voucher=>`<div class="info-line"><div><strong>${esc(voucher.name)}</strong><p class="small muted">消耗 ${voucher.coins} 币 · ${voucher.used?'已兑现':'待兑现'}</p></div>${voucher.used?'<span class="badge green">已兑现</span>':`<button class="btn small-btn" data-use-voucher="${voucher.id}">标记已兑现</button>`}</div>`).join(''):'<p class="suite-empty">兑换后会留下一张奖励券，真正享用时再标记兑现。</p>'}</section>`;}
function challengePage(){const challenge=state.preview.challenge,progress=learningProgress();return `<section class="card"><div class="section-head"><h2>给自己一个小挑战</h2><span class="candidate">示例</span></div><h3>完成两次有成果的复习</h3><p class="dashboard-quote">在两次不同的学习行动后，留下具体投入或成果，并确认入账。</p><div class="progress"><span style="width:${Math.min(100,progress/2*100)}%"></span></div><p class="small muted">${Math.min(2,progress)} / 2 次 · 示例奖励 +12 币</p><div class="record-actions">${!challenge?'<button class="btn primary" data-suite="accept-challenge">接受挑战</button>':challenge.claimed?'<span class="badge green">挑战奖励已领取</span>':progress>=2?'<button class="btn primary" data-suite="claim-challenge">确认领取奖励</button>':'<span class="badge">进行中 · 按自己的节奏继续</span>'}<button class="link-btn" data-nav="plans">去安排具体行动 →</button></div></section>`;}
function showPreviewDialog(title,body,action,label='确认'){pendingModal=action;document.getElementById('preview-dialog-content').innerHTML=`<div class="head"><h2>${esc(title)}</h2><button class="close-btn" data-suite="close-modal" aria-label="关闭">×</button></div>${body}<div id="modal-error" class="error-box" hidden></div><div class="actions"><button class="btn" data-suite="close-modal">取消</button><button class="btn primary" data-suite="confirm-modal">${esc(label)}</button></div>`;document.getElementById('preview-dialog').showModal();}
function modalError(text){const box=document.getElementById('modal-error');box.textContent=text;box.hidden=false;}
function closePreviewDialog(){document.getElementById('preview-dialog').close();pendingModal=null;}
function openRecord(id){const record=state.records.find(record=>record.id===id);if(!record)return;if(record.kind==='diary'){setDemoDate(record.date);setPage('review');}else{detailId=id;setPage('detail');}}
function analyzeRecord(){
  const record=state.records.find(record=>record.id===detailId);if(!record||record.confirmed||record.analysisStatus==='queued')return;
  if(state.preview.ai.source==='off'){showPreviewDialog('AI 目前已关闭','<p class="dashboard-quote">原文可以照常保存。需要分析时，在模型设置中主动选择一个来源。</p>',()=>{closePreviewDialog();setPage('settings');},'去模型设置');return;}
  if(state.preview.ai.status!=='ready'){showPreviewDialog('先验证模型配置','<p class="dashboard-quote">配置已经保存，但还没有通过示例测试。先验证，再发起分析。</p>',()=>{closePreviewDialog();setPage('settings');},'去验证');return;}
  const supplement=document.getElementById('event-supplement')?.value.trim();if(supplement){record.supplement=supplement;record.version=(record.version||1)+1;}
  record.analysisIntent='now';record.goalId=document.getElementById('event-goal').value;const grade=document.getElementById('event-grade').value,outcome=document.getElementById('analysis-outcome')?.value||'ready';
  record.analysisStatus='queued';record.suggestion=null;const version=record.version||1;persist();render();
  setTimeout(()=>{if(record.version!==version||record.analysisStatus!=='queued')return;record.analysisStatus=outcome;if(outcome==='ready'){const goal=state.preview.goals.find(goal=>goal.id===record.goalId),bonus=goal?.main?{light:1,steady:3,deep:5}[grade]:0;record.suggestion={attribute:'智力',delta:{light:.2,steady:.5,deep:.8}[grade],grade:{light:'轻量行动',steady:'明确投入／进展',deep:'持续投入／具体成果'}[grade],bonus,coins:2+bonus,reason:'针对这次记录中的实际行动，展示一份独立建议。需要补充时只围绕这件事追问。',version};}persist();if(currentPage==='detail'&&detailId===record.id)render();},450);
}
function confirmRecord(){const record=state.records.find(record=>record.id===detailId);if(!record?.suggestion||record.confirmed)return;if(!state.preview.neutral){showPreviewDialog('先选择游戏起点','<p class="dashboard-quote">原文和建议已经保留。你之前选择先使用未评估基线，之后再迁入旧数据。</p>',()=>{state.preview.neutral=true;persist();closePreviewDialog();render();},'使用未评估基线');return;}
  const canonical=record.sameFactAs||record.id;if(state.preview.coinLedger.some(row=>row.ref===canonical)||state.ledger.some(row=>row.recordId===canonical)){record.confirmed=true;record.reusedSettlement=true;record.analysisStatus='confirmed';persist();render();return;}
  record.confirmed=true;record.analysisStatus='confirmed';state.preview.coinLedger.push({id:'event-'+canonical,ref:canonical,amount:record.suggestion.coins,title:record.title,source:'事件确认 · 示例'});persist();render();}
function previewChecklist(){return heading('审阅这一版','先体验，再决定要把哪些方案交给 Writer。','完整体验 Demo · 待你确认')+`<div class="proposal-note">这不是正式应用。所有账号、模型、邮件、分析和奖励都是本机示例；不要填写真实密码或 Key。你确认后才定稿开发文档，不会从这里自动启动 Writer。</div><section class="card"><h2>先走一遍日常路径</h2><div class="demo-grid" style="margin-top:18px">${previewDirectory().map(([page,title,desc])=>`<button data-nav="${page}">${title}<small>${desc}</small></button>`).join('')}</div></section><section class="card" style="margin-top:20px"><div class="section-head"><h2>本版体验意见</h2><button class="link-btn" data-suite="download-feedback">下载意见记录</button></div><p class="small muted">选项只存本机，最终确认仍请在聊天里告诉我。候选不等于已经批准实施。</p>${decisionItems.map(([id,title,desc,status])=>`<article class="approval-item"><div class="row between"><h3>${title}</h3><span class="${status==='候选'?'candidate':'badge gray'}">${status}</span></div><p>${desc}</p><div class="approval-options">${['接受这版','需要调整','暂缓'].map(choice=>`<button data-decision="${id}" data-choice-value="${choice}" aria-pressed="${state.preview.decisions[id]===choice}">${choice}</button>`).join('')}</div></article>`).join('')}<div class="form-grid"><label>还想调整的地方<textarea id="preview-feedback" placeholder="可以写页面、按钮或一段操作路径。">${esc(state.preview.feedback)}</textarea></label><button class="btn primary" data-suite="save-feedback">保存本机意见</button></div></section><section class="card" style="margin-top:20px"><h2>切换体验身份</h2><p class="dashboard-quote">普通日常账号与管理身份分开体验。这里只改变虚构预览身份，不是实际授权机制。</p><div class="row wrap"><button class="btn ${state.preview.role==='user'?'primary':''}" data-role="user">日常账号</button><button class="btn ${state.preview.role==='admin'?'primary':''}" data-role="admin">管理身份</button></div><p class="subtle-note">App／微信小程序、旧数据迁移和公网部署属于后续工作，本版不承诺已完成。</p></section>`;}
function render(){
  if(!state.preview)return;if(state.preview.role==='admin'&&!['admin','admin-users','admin-notices','admin-site','admin-audit','admin-account','preview'].includes(currentPage))currentPage='admin';if(state.preview.role!=='admin'&&currentPage.startsWith('admin'))currentPage='admin';nav();document.getElementById('demo-date').value=state.date;
  const pages={today,handbook,detail:eventDetail,plans:planOverview,goals:goalsPage,review,growth,my:myPage,settings:modelSettings,security:securityPage,export:exportPage,admin:adminPage,'admin-users':adminUsersPage,'admin-notices':adminNoticesPage,'admin-site':adminSitePage,'admin-audit':adminAuditPage,'admin-account':adminAccountPage,auth:authPage,preview:previewChecklist,guide};
  document.getElementById('app').innerHTML=(pages[currentPage]||today)();
  if(currentPage==='handbook')document.getElementById('handbook-scope').value=handbookScope;
  if(currentPage==='export')document.getElementById('export-kind').value=exportOptions.kind;
  if(currentPage==='today'){
    const composer=document.querySelector('.composer-foot');if(composer)composer.insertAdjacentHTML('beforebegin',`<div class="row wrap" style="margin:0 0 16px"><label class="small muted" for="save-intent">保存后</label><select id="save-intent" class="btn small-btn"><option value="later">先保存，稍后分析</option><option value="now">现在分析</option><option value="never">只记录，不分析</option></select><details class="small muted"><summary>补记其他日期</summary><input type="date" id="event-date" value="${state.date}" style="max-width:180px;margin-top:8px"></details></div>`);
  }
}
function handlePreviewAction(action){
  if(action==='close-modal'){closePreviewDialog();return;}
  if(action==='confirm-modal'){pendingModal?.();return;}
  if(action==='dismiss-notice'){state.preview.noticeDismissed=state.preview.notice.version;persist();render();return;}
  if(action==='search'){handbookQuery=document.getElementById('handbook-search').value.trim();handbookScope=document.getElementById('handbook-scope').value;handbookPage=0;render();return;}
  if(action==='neutral'){state.preview.neutral=true;persist();render();return;}
  if(action==='analyze-event'){analyzeRecord();return;}
  if(action==='cancel-event'){const record=state.records.find(record=>record.id===detailId);record.analysisStatus='idle';persist();render();return;}
  if(action==='confirm-event'){confirmRecord();return;}
  if(action==='edit-event'){const record=state.records.find(record=>record.id===detailId);showPreviewDialog('编辑事件原文',`<div class="form-grid"><label>原文<textarea id="edit-event-text">${esc(record.content)}</textarea></label></div><p class="subtle-note">原文变动后，旧的未确认建议会失效。已入账更正需另走正式冲正流程。</p>`,()=>{const text=document.getElementById('edit-event-text').value.trim();if(!text){modalError('原文不能为空。');return;}if(record.confirmed){modalError('这条已入账。正式更正与冲正流程仍待确认，本版不直接改账。');return;}record.content=text;record.title=text.slice(0,30);record.version=(record.version||1)+1;record.analysisStatus='idle';record.suggestion=null;persist();closePreviewDialog();render();},'保存原文');return;}
  if(action==='related'){const candidates=state.records.filter(record=>record.kind!=='diary'&&record.id!==detailId);showPreviewDialog('疑似关联 · 交互示例',`<p class="dashboard-quote">AI 只能建议关联，由你决定。这里列出示例原文，不代表已做语义检测。</p><div class="form-grid"><label>选择同一次行动的原文<select id="related-record"><option value="">不关联，保持独立</option>${candidates.map(record=>`<option value="${record.id}">${esc(record.title)}</option>`).join('')}</select></label></div><p class="subtle-note">两份原文保留；同一实际行动不重复计奖。</p>`,()=>{const record=state.records.find(record=>record.id===detailId);if(record.confirmed){modalError('已入账记录不能通过关联改写旧账。');return;}record.sameFactAs=document.getElementById('related-record').value||null;persist();closePreviewDialog();render();},'确认关联');return;}
  if(action==='add-goal'){const name=document.getElementById('goal-name').value.trim();if(!name){toast('先写下目标名称。');return;}state.preview.goals.push({id:crypto.randomUUID(),name,note:document.getElementById('goal-note').value.trim(),main:false});persist();render();return;}
  if(action==='claim-achievement'){if(state.preview.claimed.includes('first-project'))return;state.preview.claimed.push('first-project');state.preview.coinLedger.push({id:'achievement-first-project',amount:10,title:'第一次完成云端部署',source:'成就奖励 · 示例'});persist();render();return;}
  if(action==='ignore-achievement'){toast('可以稍后再决定，这次不发放奖励。');return;}
  if(action==='accept-challenge'){state.preview.challenge={accepted:true,claimed:false};persist();render();return;}
  if(action==='claim-challenge'){const challenge=state.preview.challenge;if(!challenge||challenge.claimed||learningProgress()<2)return;challenge.claimed=true;state.preview.coinLedger.push({id:'challenge-2',amount:12,title:'完成两次有成果的复习',source:'挑战奖励 · 示例'});persist();render();return;}
  if(action==='add-product'){showProductForm();return;}
  if(action==='save-feedback'){state.preview.feedback=document.getElementById('preview-feedback').value;persist();toast('意见已存本机，请在聊天里告诉我最终决定。');return;}
  if(action==='download-feedback'){downloadArtifact({name:'LifeXP-Demo-意见.json',type:'application/json',text:JSON.stringify({scope:'本机候选意见，不是 Writer 开工指令',choices:state.preview.decisions,feedback:state.preview.feedback},null,2)});return;}
  handleSettingsAction(action);
}
document.addEventListener('click',event=>{
  const button=event.target.closest('button');if(!button)return;
  if(button.id==='create-plan'){
    event.stopImmediatePropagation();const before=state.plans.length;createPlan();if(state.plans.length===before)return;
    const plan=state.plans.at(-1);if(plan.goal){let goal=state.preview.goals.find(goal=>goal.name===plan.goal);if(!goal){goal={id:crypto.randomUUID(),name:plan.goal,note:'来自你主动设置的计划',main:false};state.preview.goals.push(goal);}if(plan.main){for(const candidate of state.preview.goals)candidate.main=candidate===goal;for(const candidate of state.plans)candidate.main=candidate.goal===goal.name;}}persist();render();return;
  }
  if(button.id==='save-event'){
    event.stopImmediatePropagation();captureDraft();const text=document.getElementById('event-input').value.trim();if(!text){toast('先写一点想留下的内容。');return;}
    const date=document.getElementById('event-date')?.value||state.date,intent=document.getElementById('save-intent').value;
    const record={id:'event-'+crypto.randomUUID(),kind:'event',date,time:'刚刚',title:text.slice(0,30)+(text.length>30?'…':''),content:text,version:1,analysisIntent:intent,analysisStatus:'idle'};state.records.unshift(record);sessionDraft='';saveComposerDraft();persist();
    if(intent==='now'){detailId=record.id;setPage('detail');analyzeRecord();}else{render();toast('事件原文已保存在本机预览。');}return;
  }
  if(button.dataset.suite){event.stopImmediatePropagation();handlePreviewAction(button.dataset.suite);return;}
  if(button.dataset.openRecord){event.stopImmediatePropagation();openRecord(button.dataset.openRecord);return;}
  if(button.dataset.growth){event.stopImmediatePropagation();growthTab=button.dataset.growth;setPage('growth');return;}
  if(button.dataset.handbook){event.stopImmediatePropagation();handbookKind=button.dataset.handbook;handbookPage=0;render();return;}
  if(button.dataset.pageStep){event.stopImmediatePropagation();handbookPage+=Number(button.dataset.pageStep);render();return;}
  if(button.dataset.mainGoal){event.stopImmediatePropagation();const goal=state.preview.goals.find(goal=>goal.id===button.dataset.mainGoal);for(const candidate of state.preview.goals)candidate.main=candidate===goal;for(const plan of state.plans)plan.main=plan.goal===goal.name;persist();render();return;}
  if(button.dataset.redeem){event.stopImmediatePropagation();const product=state.preview.products.find(product=>product.id===button.dataset.redeem),redemptionId=crypto.randomUUID();showPreviewDialog('兑换这个奖励？',`<h3 style="margin-top:17px">${esc(product.name)}</h3><div class="info-line"><span>本次消耗</span><strong class="money">${product.coins} 币</strong></div><div class="info-line"><span>兑换后余额</span><strong class="money">${balance()-product.coins} 币</strong></div><p class="subtle-note">确认后生成一张待兑现奖励券，真正享用时再标记。</p>`,()=>{if(state.preview.vouchers.some(voucher=>voucher.id===redemptionId))return;if(balance()<product.coins){modalError('金币不足，未扣除。');return;}state.preview.vouchers.push({id:redemptionId,name:product.name,coins:product.coins,used:false});state.preview.coinLedger.push({id:redemptionId,amount:-product.coins,title:'兑换「'+product.name+'」',source:'奖励券 · 示例'});persist();closePreviewDialog();render();},'确认兑换');return;}
  if(button.dataset.price){event.stopImmediatePropagation();showProductForm(button.dataset.price);return;}
  if(button.dataset.useVoucher){event.stopImmediatePropagation();const voucher=state.preview.vouchers.find(voucher=>voucher.id===button.dataset.useVoucher);if(voucher)voucher.used=true;persist();render();return;}
  if(button.dataset.decision){event.stopImmediatePropagation();state.preview.feedback=document.getElementById('preview-feedback').value;state.preview.decisions[button.dataset.decision]=button.dataset.choiceValue;persist();render();return;}
  if(button.dataset.role){event.stopImmediatePropagation();const feedback=document.getElementById('preview-feedback');if(feedback)state.preview.feedback=feedback.value;adminAccountOrigin=null;state.preview.role=button.dataset.role;persist();setPage(state.preview.role==='admin'?'admin':'today');return;}
  if(button.dataset.authTab){event.stopImmediatePropagation();authTab=button.dataset.authTab;if(button.dataset.nav)setPage(button.dataset.nav);else render();return;}
},true);
function startAI(){if(state.preview.ai.source==='off'||state.preview.ai.status!=='ready'){showPreviewDialog('选择可用的 AI 来源','<p class="dashboard-quote">日记原文已保留，需要辅助回顾时先启用并验证模型。</p>',()=>{closePreviewDialog();setPage('settings');},'去模型设置');return;}routineStartAI();}
function confirmPlan(id){
  const plan=state.plans.find(plan=>plan.id===id),item=plan&&state.occurrences[occurrenceKey(plan)];if(!item?.suggestion||item.settled)return;
  const record=state.records.find(record=>record.id===item.recordId),canonical=record?.sameFactAs||item.recordId;
  if(state.preview.coinLedger.some(row=>row.ref===canonical)||state.ledger.some(row=>row.recordId===canonical)){
    item.settled=true;item.resultConfirmed=true;item.reusedSettlement=true;persist();render();return;
  }
  routineConfirmPlan(id);
}
function plannedRow(plan){const item=state.occurrences[occurrenceKey(plan)];if(item?.reusedSettlement)return `<article class="plan-row"><div class="row between"><h3>${esc(plan.name)}</h3><span class="badge green">已关联原入账</span></div><p class="plan-meta">${esc(plan.goal||'独立计划')}</p><p class="small muted">同一次实际行动，不重复发放属性与金币。</p></article>`;return routinePlannedRow(plan);}
